/bin/zsh -lc "python3 - <<'PY'
import json
from pathlib import Path
actual = json.loads(Path('config.json').read_text())
expected = {'project': 'catalog-api', 'cache': {'ttl_seconds': 300, 'max_entries': 500, 'eviction_policy': 'fifo', 'namespace': 'catalog-shared', 'cache_misses': True}}
def exact(a, b):
    assert type(a) is type(b), (a, b)
    if isinstance(b, dict):
        assert a.keys() == b.keys()
        for k in b:
            exact(a[k], b[k])
    else:
        assert a == b, (a, b)
exact(actual, expected)
print('Validated complete JSON: all keys, values, and types match approved v2; only ttl_seconds changed from v1 (600 to 300 seconds).')
PY"

